-- Table structure for table nails_sections
CREATE TABLE `nails_sections` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_key` varchar(50) NOT NULL,
  `section_name` varchar(100) NOT NULL,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`content`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `section_key` (`section_key`),
  KEY `idx_section_key` (`section_key`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table nails_sections
INSERT INTO nails_sections (section_key, section_name, content) VALUES ('hero', 'Hero Banner & Media (Video / Image)', '{\"titlePrefix\":\"Nails,\",\"titleHighlight\":\"done right.\",\"description\":\"Gel, acrylic, extensions or a simple mani-pedi — every nail service handled by an artist trained for precision, hygiene, and radiant luxury.\"}') ON DUPLICATE KEY UPDATE section_name = VALUES(section_name), content = VALUES(content);
INSERT INTO nails_sections (section_key, section_name, content) VALUES ('showcase', 'Nails Services Showcase Cards', '{\"id\":\"nail-services\",\"category\":\"Nails\",\"eyebrow\":\"Precision Nail Architecture\",\"title\":\"Nails Services\",\"subtitle\":\"From classic Parisian French art and high-durability acrylics to bespoke 3D bridal motifs and relaxing therapeutic pedicures.\",\"items\":[{\"id\":\"nail-art\",\"title\":\"French Nail Art\",\"short_desc\":\"Take advantage of our French nail art services and embrace classic elegance. Our highly trained professionals create elegant precise designs that fit your aesthetic.\",\"description\":\"At KNK Awadh best nail art in Lucknow, we bring the allure of Parisian chic to your fingertips. Because your nails should not just be adorned, but a masterpiece of grace and sophistication. We also offer classic French polish to make your nails look natural, as well as trendy French polish for those who enjoy experimenting with color. Taking care of your nails is the key to conveying the language of timeless beauty.\",\"image\":\"/assets/images/services/nail-french.webp\",\"category\":\"Nails\",\"filter_category\":\"Art & French\",\"highlights\":[\"Parisian Chic\",\"High Gloss\",\"Bespoke Apex\"],\"url\":\"/services/nails/nail-art\",\"display_order\":1},{\"id\":\"nail-art-bespoke\",\"title\":\"Nail Art\",\"short_desc\":\"At KNK Awadh best nail art in Lucknow we offer exceptional nail spa gel nails and acrylic nails as well as pedicures and manicures.\",\"description\":\"In addition to nail extensions in Lucknow, we also offer French nails, chrome glaze, 3D bridal motifs, encapsulated flowers, and bespoke art. It is a luxurious experience and all the services are top-notch with experienced certified nail artists.\",\"image\":\"/assets/images/services/nail-art.webp\",\"category\":\"Nails\",\"filter_category\":\"Art & French\",\"highlights\":[\"3D Bridal Motifs\",\"Chrome Glaze\",\"Certified Artists\"],\"url\":\"/services/nails/nail-art\",\"display_order\":2},{\"id\":\"gel-nails\",\"title\":\"Gel Polish\",\"short_desc\":\"KNK Awadh\'s Gel Nail Service transforms your nails with timeless elegance and adaptable designs. Our Gel Nail Service offers a variety of solutions to enhance your style.\",\"description\":\"Our specialized UV-cured application technique ensures that both aesthetics and nail health are maintained, keeping your nails\' original integrity intact. Whether you\'re looking for extreme durability or stunning high-gloss shine for 3 to 4 weeks, KNK Awadh is the premier destination.\",\"image\":\"/assets/images/services/nail-gel-polish.webp\",\"category\":\"Nails\",\"filter_category\":\"Gel & Acrylic\",\"highlights\":[\"UV-Cured Shine\",\"3-4 Weeks Wear\",\"Zero Chipping\"],\"url\":\"/services/nails/gel-nails\",\"display_order\":3},{\"id\":\"nail-extensions\",\"title\":\"Gel Nail Extension\",\"short_desc\":\"KNK Awadh offers an amazing Gel Nail Extension treatment that combines durability and artistic skill to transform your nails with lightweight strength.\",\"description\":\"Our trained experts create long-lasting vivid nail extensions with high-quality gel materials in almond, coffin, stiletto, and square shapes. Experience structural apex balance, flawless shine, and natural feel at an affordable price.\",\"image\":\"/assets/images/services/nail-gel-ext.webp\",\"category\":\"Nails\",\"filter_category\":\"Gel & Acrylic\",\"highlights\":[\"Lightweight Strength\",\"Natural Feel\",\"Custom Shapes\"],\"url\":\"/services/nails/nail-extensions\",\"display_order\":4},{\"id\":\"acrylic-nails\",\"title\":\"Acrylic Nail Extension\",\"short_desc\":\"We offer the finest in acrylic nail extensions in Lucknow. Our experts provide durable sculpts and explain the many benefits of reinforced acrylic.\",\"description\":\"Get glitzy and beautiful designs with long-lasting, robust nails that withstand daily activities. Our acrylic extensions provide thickness, sculpted length, and unbreakable strength to your natural nails while staying impeccably stylish.\",\"image\":\"/assets/images/services/nail-acrylic.webp\",\"category\":\"Nails\",\"filter_category\":\"Gel & Acrylic\",\"highlights\":[\"Reinforced Sculpt\",\"Long-Lasting\",\"High Durability\"],\"url\":\"/services/nails/acrylic-nails\",\"display_order\":5},{\"id\":\"manicure\",\"title\":\"Luxury Manicure\",\"short_desc\":\"Gentle nail shaping, cuticle therapy, thermal paraffin wraps, and relaxing hand pressure-point massage.\",\"description\":\"Revitalize tired hands with botanical scrubs, dead-skin buffing, deep moisture infusion, and expert nail polishing for velvety soft, radiant hands that turn heads.\",\"image\":\"/assets/images/services/nail-manicure.webp\",\"category\":\"Nails\",\"filter_category\":\"Spa & Care\",\"highlights\":[\"Cuticle Therapy\",\"Thermal Paraffin\",\"Acupressure Massage\"],\"url\":\"/services/nails/manicure\",\"display_order\":6},{\"id\":\"pedicure\",\"title\":\"Therapeutic Pedicure\",\"short_desc\":\"Aromatherapy foot soak, callus softening, exfoliating scrub, and nourishing hydration mask for total foot wellness.\",\"description\":\"Relax as our therapists soothe tired feet, relieve stress points, soften cracked heels, and finish with immaculate cuticle grooming and high-shine polish.\",\"image\":\"/assets/images/services/nail-pedicure.webp\",\"category\":\"Nails\",\"filter_category\":\"Spa & Care\",\"highlights\":[\"Aromatherapy Soak\",\"Callus Softening\",\"Hydration Mask\"],\"url\":\"/services/nails/pedicure\",\"display_order\":7}]}') ON DUPLICATE KEY UPDATE section_name = VALUES(section_name), content = VALUES(content);
INSERT INTO nails_sections (section_key, section_name, content) VALUES ('menu', 'Treatment Menu (Categories & Items)', '{\"eyebrow\":\"What We Do\",\"title\":\"Our nail\",\"titleHighlight\":\"services.\",\"menuTitle\":\"The full menu\",\"categories\":[{\"category\":\"Nail Extensions\",\"items\":[\"Nail Cut\",\"Nail Filing\",\"Nail Paint Application\",\"Gel Paint Removal\",\"Gel Paint Application\",\"Temporary Nail Extensions\",\"Gel Nail Extensions\",\"Acrylic Nail Extensions\"]},{\"category\":\"Mani / Pedi\",\"items\":[\"Basic\",\"O3+\",\"Alga\",\"Bombini\",\"Biscotti\"]},{\"category\":\"Art & French\",\"items\":[\"French Tips\",\"Ombre Glitter\",\"Chrome Mirror\",\"Cat Eye Gel\",\"3D Motifs\"]}]}') ON DUPLICATE KEY UPDATE section_name = VALUES(section_name), content = VALUES(content);
INSERT INTO nails_sections (section_key, section_name, content) VALUES ('process', 'Process Steps (How It Works)', '{\"eyebrow\":\"How It Works\",\"title\":\"Simple, from\",\"titleHighlight\":\"start to finish.\",\"steps\":[{\"n\":\"01\",\"title\":\"Choose Your Service\",\"text\":\"Browse the list below or tell us the occasion — we\'ll suggest what fits.\"},{\"n\":\"02\",\"title\":\"Book a Slot\",\"text\":\"Call, WhatsApp, or fill the form and pick a time that works for you.\"},{\"n\":\"03\",\"title\":\"Meet Your Artist\",\"text\":\"You\'re matched with the specialist best suited to what you need.\"},{\"n\":\"04\",\"title\":\"Leave Glowing\",\"text\":\"Walk out looking — and feeling — exactly the way you wanted to.\"}]}') ON DUPLICATE KEY UPDATE section_name = VALUES(section_name), content = VALUES(content);
INSERT INTO nails_sections (section_key, section_name, content) VALUES ('cta', 'Call to Action', '{\"eyebrow\":\"Ready When You Are\",\"title\":\"Let\'s find\",\"titleHighlight\":\"your look.\",\"description\":\"Call us or send a message — we\'ll help you pick the right service and the right artist for your occasion.\",\"phone\":\"+919559321711\",\"phoneText\":\"Call Now\",\"whatsapp\":\"https://wa.me/918881000552\",\"whatsappText\":\"Chat on WhatsApp\"}') ON DUPLICATE KEY UPDATE section_name = VALUES(section_name), content = VALUES(content);
